args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-remaining-maps/transport');source(file.path(W,'common_simulated.R'));set.seed(20261029)
# V23: independently generated maritime-path display over real world polygons.
world<-rnaturalearth::ne_countries(scale='small',returnclass='sf');world<-world[world$continent!='Antarctica',];wg<-file.path(W,'naturalearth_world.gpkg');if(file.exists(wg))unlink(wg);st_write(world,wg,quiet=TRUE)
routes<-list(matrix(c(-74,40,-65,37,-45,42,-20,47,-6,50,4,52),ncol=2,byrow=TRUE),matrix(c(4,52,-6,50,-13,38,-5,36,10,37,25,34,32,31,33,28,43,13,51,12,60,20,56,25),ncol=2,byrow=TRUE),matrix(c(43,13,58,7,79,0,95,6,103,1,110,6,116,20,121,31),ncol=2,byrow=TRUE),matrix(c(103,1,111,-6,119,-17,115,-32),ncol=2,byrow=TRUE),matrix(c(-74,40,-71,22,-79,9,-85,6,-100,13,-118,33),ncol=2,byrow=TRUE),matrix(c(-74,40,-65,15,-40,-3,-43,-23),ncol=2,byrow=TRUE),matrix(c(-15,48,-23,21,-12,-2,6,-20,18,-35,40,-33,60,-15,80,0,103,1),ncol=2,byrow=TRUE),matrix(c(121,31,133,32,150,30,175,28),ncol=2,byrow=TRUE),matrix(c(-179,28,-155,29,-132,30,-118,33),ncol=2,byrow=TRUE),matrix(c(151,-34,167,-34,178,-10),ncol=2,byrow=TRUE),matrix(c(-179,-10,-140,5,-105,15,-118,33),ncol=2,byrow=TRUE),matrix(c(122,31,131,34,141,37),ncol=2,byrow=TRUE))
rr<-list();ii<-0
for(r in seq_along(routes)){a<-routes[[r]];for(j in 1:(nrow(a)-1)){for(rep in 1:18){ii<-ii+1;t<-seq(0,1,length.out=100);rr[[ii]]<-data.frame(x=a[j,1]+t*(a[j+1,1]-a[j,1])+rnorm(100,0,.55),y=a[j,2]+t*(a[j+1,2]-a[j,2])+rnorm(100,0,.45),route=r)}}};dd<-do.call(rbind,rr);dd$x<-round(dd$x*2)/2;dd$y<-round(dd$y*2)/2;dd<-aggregate(route~x+y,dd,length);names(dd)[3]<-'synthetic_path_support';dd$co2_kg_cell<-dd$synthetic_path_support^2.1*500;dd$log_co2<-log10(dd$co2_kg_cell);export(dd,'asf23_synthetic_shipping_cells')
pal<-c('#5D2CE2','#228EE2','#60C4DC','#FFE895','#F5AF29','#EC5327','#BD2136');base<-function(extent=NULL){p<-ggplot()+geom_point(data=dd,aes(x,y,colour=log_co2),shape=15,size=.55,alpha=.85)+geom_sf(data=world,fill='#FFF9F0',colour='#C4C9C8',linewidth=.08)+scale_colour_gradientn(colours=pal,limits=c(2,8),oob=scales::squish,name='CO2 (kg/cell)',breaks=c(2,4,6,8),labels=c('1e2','1e4','1e6','1e8'),guide=guide_colourbar(barwidth=unit(65,'mm'),barheight=unit(3,'mm'),title.position='top'))+th;if(is.null(extent))p+coord_sf(crs='+proj=robin',default_crs=4326,datum=NA,ylim=c(-65,85))else p+coord_sf(xlim=extent[1:2],ylim=extent[3:4],datum=NA,expand=FALSE)}
main<-base()+theme(legend.position='bottom');circlemap<-function(ext,title){center<-c(mean(ext[1:2]),mean(ext[3:4]));crs<-sprintf('+proj=laea +lat_0=%f +lon_0=%f +datum=WGS84',center[2],center[1]);box<-st_transform(st_as_sfc(st_bbox(c(xmin=ext[1],xmax=ext[2],ymin=ext[3],ymax=ext[4]),crs=st_crs(4326))),crs);bb<-st_bbox(box);r<-min(bb['xmax']-bb['xmin'],bb['ymax']-bb['ymin'])/2;origin<-st_transform(st_sfc(st_point(center),crs=4326),crs);circ<-st_buffer(origin,r,nQuadSegs=120);land<-suppressWarnings(st_crop(world,c(xmin=ext[1]-5,xmax=ext[2]+5,ymin=ext[3]-5,ymax=ext[4]+5)));land<-suppressWarnings(st_intersection(st_transform(st_make_valid(land),crs),circ));dots<-st_transform(st_as_sf(dd,coords=c('x','y'),crs=4326,remove=FALSE),crs);dots<-dots[lengths(st_intersects(dots,circ))>0,];ggplot()+geom_sf(data=dots,aes(colour=log_co2),shape=15,size=.65)+geom_sf(data=land,fill='#FFF9F0',colour='#C4C9C8',linewidth=.12)+geom_sf(data=st_sf(geometry=circ),fill=NA,colour='#30343B',linewidth=.25)+scale_colour_gradientn(colours=pal,limits=c(2,8),oob=scales::squish,guide='none')+coord_sf(datum=NA,expand=FALSE)+labs(title=title)+th+theme(legend.position='none',plot.title=element_text(hjust=.5,size=7))}
p<-main/(circlemap(c(-12,12,30,55),'Gibraltar')|circlemap(c(44,63,10,30),'Hormuz')|circlemap(c(94,112,-6,12),'Malacca'))+plot_layout(heights=c(2.1,1))
finish('ASF-V23',p,'asf23_shipping_inset_structure',183,150,'World route-density visual with three circular zooms; fixed synthetic waypoint paths, jitter and cell weights. No original2015AIS or STEAM3 emission grid. Numeric scale is training-only synthetickg/cell; route positions are synthetic display paths. Editorial headline/prose removed under canvas text policy.','NaturalEarth110m real country polygons; Robinson global projection and longitude/latitude inset crops',4)
# V29: two quantitative panels above actual Rio municipality map; synthetic travel scenario.
allrio<-st_read(file.path(W,'rio_state_municipalities.geojson'),quiet=TRUE);rio<-st_make_valid(allrio[allrio$id=='3304557',]);stopifnot(nrow(rio)==1);n<-xy(pts(rio,70));n$reduced_origin<-round(runif(nrow(n),0,480));n$reduced_destination<-round(runif(nrow(n),0,480));e<-edges(n,2);e$ridership<-round(runif(nrow(e),1000,5000));export(n,'asf29_synthetic_rio_origins');export(e,'asf29_synthetic_rio_routes')
x<-seq(1000,10000,1000);curves<-do.call(rbind,lapply(1:3,function(k){data.frame(reduced_pairs=x,distance=paste(k,'km'),marginal=1.5+((x-1000)/9000)^(1+.1*k)*(9+1.7*k),uniform=.2+((x-1000)/9000)*(2.7+.5*k),reduced_demand=.18+((x-1000)/9000)*(2.8-.23*k))}));ln<-rbind(data.frame(curves[,c('reduced_pairs','distance')],strategy='Marginal',reduced_time=curves$marginal),data.frame(curves[,c('reduced_pairs','distance')],strategy='Uniform',reduced_time=curves$uniform));export(curves,'asf29_synthetic_travel_curves');cc<-c('1 km'='#409B85','2 km'='#D57434','3 km'='#7772AB')
tb<-theme_bw(base_family='Arial',base_size=7)+theme(panel.grid=element_blank(),axis.text=element_text(size=7),axis.title=element_text(size=7),legend.text=element_text(size=7),legend.title=element_text(size=7),legend.position='top',plot.tag=element_text(size=8,face='bold'),plot.margin=margin(2,2,2,2))
a<-ggplot(ln,aes(reduced_pairs,reduced_time,colour=distance,linetype=strategy,shape=strategy))+geom_line(linewidth=.45)+geom_point(size=1.5)+scale_colour_manual(values=cc,name=NULL)+scale_shape_manual(values=c(Marginal=16,Uniform=17),name=NULL)+scale_linetype_manual(values=c(Marginal='solid',Uniform='dashed'),name=NULL)+labs(x='Reduced OD pairs',y='Reduced travel time (%)',tag='a')+tb+theme(legend.text=element_text(size=7),legend.key.width=unit(5,'mm'))+guides(colour=guide_legend(nrow=1),linetype=guide_legend(nrow=1),shape=guide_legend(nrow=1))
b<-ggplot(curves,aes(factor(reduced_pairs),reduced_demand,fill=distance))+geom_col(position=position_dodge(.8),width=.7,colour='#30343B',linewidth=.35)+scale_fill_manual(values=cc,name=NULL)+labs(x='Reduced OD pairs',y='Reduced demand (%)',tag='b')+tb+theme(axis.text.x=element_text(angle=45,hjust=1))+guides(fill=guide_legend(nrow=1))
map<-ggplot()+geom_sf(data=rio,fill='#E0E4E6',colour='#86939B',linewidth=.2)+geom_point(data=n,aes(x,y,size=reduced_origin),colour='#4C8EB4',alpha=.3)+scale_size_continuous(range=c(1,9),limits=c(0,480),name='Reduced origin demand',breaks=c(120,240,480))+geom_segment(data=e,aes(x,y,xend=xend,yend=yend,linewidth=ridership),colour='#3C9C74',alpha=.85)+scale_linewidth_continuous(range=c(.25,1.7),limits=c(1000,5000),name='Route ridership',breaks=c(1000,2000,3000,4000,5000))+geom_point(data=n,aes(x,y),shape=21,fill='white',colour='#387958',size=.65,stroke=.15)+coord_sf(datum=NA)+labs(tag='c')+th+theme(legend.position='right',legend.box='vertical')
p<-(a|b)/map+plot_layout(heights=c(1,1.45))
finish('ASF-V29',p,'asf29_rio_map_distribution_structure',183,164,'Two synthetic response charts and synthetic node/route demand map on real Rio municipality boundary. All curves, OD pairs, node positions, flows and reduced demand are simulated fixture values; no traffic model or original-data inference. Map simplified to origin-demand bubbles and route-width legend; original spatial density surfaces unavailable.','IBGE-derived CC0 municipality3304557 GeoJSON fromgeodata-br;EPSG:4326; version not established',3)
